// REACTION LOOM
// Gray-Scott reaction-diffusion played as an instrument. Two chemicals share a torus: U (food) and V (the pattern).
// Each frame runs a few diffusion steps, then paints V through a gradient with optional relief shading.
// Variables are re-read every frame: the regime morphs the living pattern in place, a new seed layout restarts it.

const N = 220;                 // simulation grid, upscaled to the canvas
const W = N + 2;               // one cell of halo so the field wraps around

// feed f, kill k (Pearson's map; diffusion 1.0 / 0.5 as in Karl Sims' notes)
const REGIMES = {
  'coral growth':   [0.0545, 0.0620],
  'labyrinth':      [0.0290, 0.0570],
  'wandering spots':[0.0140, 0.0540],
  'solitons':       [0.0300, 0.0620],
  'holes':          [0.0390, 0.0580],
  'fingerprint':    [0.0370, 0.0600],
  'skate world':    [0.0620, 0.0609],
  'spiral waves':   [0.0180, 0.0510],
  'ferment':        [0.0260, 0.0510],
  'ribbon coral':   [0.0500, 0.0615]
};

const PALETTES = {
  'ink and bone':       ['#0b0a0f', '#2b2630', '#8f8678', '#f1ead9'],
  'verdigris and oxide':['#0d1412', '#1f4d47', '#5fa391', '#d9d08c', '#b5532c'],
  'ultraviolet lab':    ['#07040f', '#2a0d5c', '#7a2fd0', '#e45bff', '#ffe1ff'],
  'kiln glaze':         ['#150d0a', '#4a1f14', '#b4532a', '#e9a23b', '#fff0c8'],
  'deep sea phosphor':  ['#020509', '#04293a', '#0a7a8c', '#3de0c5', '#d6fff2'],
  'solar print':        ['#fdf3dd', '#f4c86a', '#e0662c', '#9b1f2e', '#2b0b1c'],
  'bruise bloom':       ['#0f0a14', '#3b1d4a', '#8a3a6a', '#d77a6d', '#f3d6a2'],
  'coal and ember':     ['#050404', '#2a0e08', '#8a2610', '#f06a1a', '#ffe28a'],
  'milk glass':         ['#e9edf0', '#bcc9d3', '#7e93a6', '#44566b', '#1b2533'],
  'acid garden':        ['#06130a', '#0f4a1a', '#52b81f', '#d9f23a', '#fff9c2']
};

const TEMPO = { 'dreamlike': 1, 'glacial': 2, 'slow': 4, 'steady': 8, 'fast': 14, 'frantic': 22 };

let U = new Float32Array(W * W), V = new Float32Array(W * W);
let U2 = new Float32Array(W * W), V2 = new Float32Array(W * W);
let off, octx, img;
const lut = new Uint8ClampedArray(256 * 3);
let lutKey = null, seedKey = null, quiet = 0, sinceSeed = 0, hiS = 0.3;

function wrap(a) {
  for (let y = 1; y <= N; y++) { a[y * W] = a[y * W + N]; a[y * W + N + 1] = a[y * W + 1]; }
  for (let x = 0; x < W; x++) { a[x] = a[N * W + x]; a[(N + 1) * W + x] = a[W + x]; }
}

function step(f, k) {
  for (let y = 1; y <= N; y++) {
    let i = y * W + 1;
    for (let x = 1; x <= N; x++, i++) {
      const u = U[i], v = V[i];
      const lu = 0.2 * (U[i - 1] + U[i + 1] + U[i - W] + U[i + W]) +
                 0.05 * (U[i - W - 1] + U[i - W + 1] + U[i + W - 1] + U[i + W + 1]) - u;
      const lv = 0.2 * (V[i - 1] + V[i + 1] + V[i - W] + V[i + W]) +
                 0.05 * (V[i - W - 1] + V[i - W + 1] + V[i + W - 1] + V[i + W + 1]) - v;
      const r = u * v * v;
      let nu = u + lu - r + f * (1 - u);
      let nv = v + 0.5 * lv + r - (k + f) * v;
      U2[i] = nu < 0 ? 0 : nu > 1 ? 1 : nu;
      V2[i] = nv < 0 ? 0 : nv > 1 ? 1 : nv;
    }
  }
  let t = U; U = U2; U2 = t;
  t = V; V = V2; V2 = t;
  wrap(U); wrap(V);
}

// a seed of the kind these regimes like: half the food gone, a quarter of the pattern chemical, a little noise
function blob(cx, cy, r) {
  for (let dy = -r; dy <= r; dy++) {
    for (let dx = -r; dx <= r; dx++) {
      if (dx * dx + dy * dy > r * r) continue;
      const x = (((cx + dx) % N) + N) % N + 1, y = (((cy + dy) % N) + N) % N + 1;
      V[y * W + x] = 0.25 + p.random(-0.01, 0.01); U[y * W + x] = 0.5;
    }
  }
}

function seed(kind) {
  U.fill(1); V.fill(0);
  const c = N >> 1;
  if (kind === 'a single drop') blob(c, c, 12);
  else if (kind === 'scattered flecks') for (let i = 0; i < 22; i++) blob(p.floor(p.random(N)), p.floor(p.random(N)), 7);
  else if (kind === 'a ring') for (let a = 0; a < 6.283; a += 0.04) blob(c + p.cos(a) * N * 0.3, c + p.sin(a) * N * 0.3, 5);
  else if (kind === 'a diagonal scar') for (let t = 0; t < N; t += 3) blob(t, t, 5);
  else if (kind === 'a pinprick grid') for (let gy = 1; gy < 6; gy++) for (let gx = 1; gx < 6; gx++) blob((gx * N) / 6, (gy * N) / 6, 6);
  else if (kind === 'twin drops') { blob(c - 42, c, 10); blob(c + 42, c + 8, 10); }
  else if (kind === 'a frame') { for (let t = 24; t < N - 24; t += 3) { blob(t, 24, 5); blob(t, N - 24, 5); blob(24, t, 5); blob(N - 24, t, 5); } }
  else if (kind === 'a spiral') for (let a = 0; a < 18; a += 0.12) blob(c + p.cos(a) * a * 5, c + p.sin(a) * a * 5, 5);
  else blob(c, c, 12);
  // a sprinkle of single-cell specks across the dish helps the touchier regimes catch
  for (let i = 0; i < W * W; i++) if (p.random() < 0.004) { V[i] = 0.5; U[i] = 0.5; }
  wrap(U); wrap(V);
  quiet = 0; sinceSeed = 0;
}

function buildLut(stops) {
  const cols = stops.map(h => [parseInt(h.slice(1, 3), 16), parseInt(h.slice(3, 5), 16), parseInt(h.slice(5, 7), 16)]);
  for (let i = 0; i < 256; i++) {
    const t = (i / 255) * (cols.length - 1), a = Math.floor(t), b = Math.min(cols.length - 1, a + 1), m = t - a;
    for (let ch = 0; ch < 3; ch++) lut[i * 3 + ch] = cols[a][ch] + (cols[b][ch] - cols[a][ch]) * m;
  }
}

function paint(relief) {
  const d = img.data;
  const ink = [lut[0], lut[1], lut[2]];
  for (let y = 0; y < N; y++) {
    for (let x = 0; x < N; x++) {
      const i = (y + 1) * W + x + 1;
      let t = V[i] / hiS; if (t > 1) t = 1;
      const gx = V[i + 1] - V[i - 1], gy = V[i + W] - V[i - W];
      let r, g, b;
      if (relief === 'a woodcut print') {
        const lv = Math.min(3, Math.floor(t * 4)) / 3, c = ((lv * 255) | 0) * 3;
        r = lut[c]; g = lut[c + 1]; b = lut[c + 2];
        if (Math.abs(gx) + Math.abs(gy) > 0.07) { r = ink[0]; g = ink[1]; b = ink[2]; }
      } else {
        const c = ((t * 255) | 0) * 3;
        r = lut[c]; g = lut[c + 1]; b = lut[c + 2];
        if (relief === 'embossed relief') {
          let m = 1 + (-0.6 * gx - 0.8 * gy) * 7; m = m < 0.45 ? 0.45 : m > 1.6 ? 1.6 : m;
          r *= m; g *= m; b *= m;
        } else if (relief === 'glazed ceramic') {
          const s = (-0.6 * gx - 0.8 * gy) * 7;
          let m = 0.85 + (s < -0.5 ? -0.5 : s > 0.5 ? 0.5 : s) * 0.5;
          const spec = s > 0.45 ? (s - 0.45) * 520 : 0;
          r = r * m + spec; g = g * m + spec; b = b * m + spec;
        } else if (relief === 'etched outlines') {
          let e = (Math.abs(gx) + Math.abs(gy)) * 15; e = e > 1 ? 1 : e;
          r += (ink[0] - r) * e * 0.9; g += (ink[1] - g) * e * 0.9; b += (ink[2] - b) * e * 0.9;
        } else if (relief === 'contour lines') {
          if ((t * 14) % 1 < 0.13) { r += (ink[0] - r) * 0.7; g += (ink[1] - g) * 0.7; b += (ink[2] - b) * 0.7; }
        } else if (relief === 'flat colour') {
          // the gradient exactly as it is
        }
      }
      const o = (y * N + x) * 4;
      d[o] = r; d[o + 1] = g; d[o + 2] = b; d[o + 3] = 255;
    }
  }
  octx.putImageData(img, 0, 0);
}

p.setup = function () {
  p.createCanvas(800, 800);
  p.pixelDensity(1);
  p.frameRate(60);
  off = document.createElement('canvas'); off.width = N; off.height = N;
  octx = off.getContext('2d'); img = octx.createImageData(N, N);
  buildLut(PALETTES['ink and bone']); lutKey = 'ink and bone';
  seed('a single drop'); seedKey = 'a single drop';
};

p.draw = function () {
  const regime = p.getSynthVar('regime') || 'coral growth';
  const layout = p.getSynthVar('seed_layout') || 'a single drop';
  const palette = p.getSynthVar('palette') || 'ink and bone';
  const relief = p.getSynthVar('relief') || 'embossed relief';
  const stir = p.getSynthVar('stir') || 'still air';
  const tempo = p.getSynthVar('tempo') || 'steady';

  if (layout !== seedKey) { seed(layout); seedKey = layout; }
  if (palette !== lutKey) { buildLut(PALETTES[palette] || PALETTES['ink and bone']); lutKey = palette; }
  const rk = REGIMES[regime] || REGIMES['coral growth'];
  let f = rk[0];
  const k = rk[1];
  if (stir === 'a slow breath') f += 0.0016 * Math.sin(p.frameCount * 0.015);

  // a freshly planted seed runs ahead of the clock for a moment, so there is something to look at straight away
  sinceSeed++;
  const boost = 1 + 5 * Math.exp(-sinceSeed / 40);
  const steps = Math.min(40, Math.round((TEMPO[tempo] || 8) * boost));
  for (let s = 0; s < steps; s++) step(f, k);

  // stirring: things dropped into the dish while it runs
  const c = N >> 1, fc = p.frameCount;
  if (stir === 'raindrops' && fc % 24 === 0) blob(p.floor(p.random(N)), p.floor(p.random(N)), 5);
  else if (stir === 'a heartbeat' && fc % 100 === 0) { for (let a = 0; a < 6.283; a += 0.05) blob(c + Math.cos(a) * N * 0.2, c + Math.sin(a) * N * 0.2, 3); }
  else if (stir === 'a conducting stylus') blob(c + p.cos(fc * 0.021) * N * 0.34, c + p.sin(fc * 0.034) * N * 0.34, 5);
  else if (stir === 'a tremor') { for (let n = 0; n < 40; n++) { const i = (1 + p.floor(p.random(N))) * W + 1 + p.floor(p.random(N)); V[i] = Math.min(1, V[i] + 0.25); } }
  else if (stir === 'a sweeping blade') {
    const a = fc * 0.008;
    for (let t = -N; t < N; t += 1) {
      const x = Math.round(c + Math.cos(a) * t), y = Math.round(c + Math.sin(a) * t);
      if (x > 0 && x <= N && y > 0 && y <= N) { const j = y * W + x; V[j] *= 0.25; U[j] = 1; }
    }
  }

  // keep it alive: if the pattern dies out, plant the seed again
  if (fc % 20 === 0) {
    let sum = 0, mx = 0;
    for (let i = W + 1; i < W * W - W - 1; i += 7) { const v = V[i]; sum += v; if (v > mx) mx = v; }
    quiet = sum < 0.6 ? quiet + 1 : 0;
    if (quiet > 3) seed(layout);
    hiS += (Math.max(0.2, mx) - hiS) * 0.4;   // brightness follows the field, so every regime fills the gradient
  }

  paint(relief);
  const ctx = p.drawingContext;
  ctx.imageSmoothingEnabled = true; ctx.imageSmoothingQuality = 'high';
  ctx.drawImage(off, 0, 0, p.width, p.height);
  const vg = ctx.createRadialGradient(400, 400, 260, 400, 400, 580);
  vg.addColorStop(0, 'rgba(0,0,0,0)'); vg.addColorStop(1, 'rgba(0,0,0,0.38)');
  ctx.fillStyle = vg; ctx.fillRect(0, 0, 800, 800);
};
